describe("Coaching record route: responses", () => {
  it("loads and shows responses only for a role holding coaching_responses.view", async () => {
    arrange(["coaching.view"]);
    const withoutView = await pageProps();
    expect(dependencies.getCoachingRecordResponses).not.toHaveBeenCalled();
    expect(withoutView.canViewResponses).toBe(false);
    expect(withoutView.responses).toEqual([]);
    expect(withoutView.responsesUnavailable).toBe(false);
    // Nothing for the link panel either.
    expect(withoutView.canManageLinks).toBe(false);
    expect(withoutView.canManage).toBe(false);
    expect(dependencies.getCoachingPublicLinks).not.toHaveBeenCalled();
    expect(dependencies.getCoachingForms).not.toHaveBeenCalled();
    expect(dependencies.getSystemSettings).not.toHaveBeenCalled();
    vi.clearAllMocks();

    arrange(["coaching.view", "coaching_responses.view"]);
    const withView = await pageProps();
    expect(dependencies.getCoachingRecordResponses).toHaveBeenCalledWith(RECORD_ID);
    expect(withView.canViewResponses).toBe(true);
    expect(withView.responses).toEqual([response]);
    expect(withView.responsesUnavailable).toBe(false);
    expect(withView.record).toBe(record);
    expect(withView.events).toEqual([]);
  });

  it("flags a permitted loader that failed (null) as unavailable instead of passing it on as empty", async () => {
    const panelRole = ["coaching.view", "coaching_responses.view", "coaching_links.manage", "coaching_forms.view"];
    arrange(panelRole, { forms: null, links: null, responses: null });
    const failed = await pageProps();
    expect(failed.responses).toEqual([]);
    expect(failed.responsesUnavailable).toBe(true);
    expect(failed.links).toEqual([]);
    expect(failed.linksUnavailable).toBe(true);
    expect(failed.canManageLinks).toBe(true);
    // A failed forms list is not "no published form" (the panel would ask to publish one).
    expect(failed.forms).toEqual([]);
    expect(failed.formsUnavailable).toBe(true);
    expect(failed.canViewForms).toBe(true);
    vi.clearAllMocks();

    // Loaded and empty is not a failure: the page shows its empty lines and opens the create form.
    arrange(panelRole, { forms: [], links: [], responses: [] });
    const empty = await pageProps();
    expect(empty.responsesUnavailable).toBe(false);
    expect(empty.linksUnavailable).toBe(false);
    expect(empty.formsUnavailable).toBe(false);
    expect(empty.links).toEqual([]);
    expect(empty.forms).toEqual([]);
  });
});

describe("Coaching record route: link panel inputs", () => {
  it("loads the forms list only for the link panel and the expiry only with settings.view", async () => {
    // coaching_forms.view alone no longer loads the forms: only the panel's version picker uses them.
    arrange(["coaching.view", "coaching_forms.view"]);
    const formsViewer = await pageProps();
    expect(dependencies.getCoachingForms).not.toHaveBeenCalled();
    expect(formsViewer.forms).toEqual([]);
    vi.clearAllMocks();

    // The panel without coaching_forms.view or settings.view: history, no forms, the default expiry.
    arrange(["coaching.view", "coaching_links.manage"]);
    const linkManager = await pageProps();
    expect(dependencies.getCoachingPublicLinks).toHaveBeenCalledWith(RECORD_ID);
    expect(dependencies.getCoachingForms).not.toHaveBeenCalled();
    expect(dependencies.getSystemSettings).not.toHaveBeenCalled();
    expect(linkManager.links).toEqual([activeLink]);
    expect(linkManager.linksUnavailable).toBe(false);
    expect(linkManager.forms).toEqual([]);
    // Not loaded for lack of permission: no failure flag, and the panel is told why the list is empty.
    expect(linkManager.formsUnavailable).toBe(false);
    expect(linkManager.canViewForms).toBe(false);
    expect(linkManager.defaultPublicLinkExpiryDays).toBeUndefined();
    vi.clearAllMocks();

    arrange(["coaching.view", "coaching.manage", "coaching_links.manage", "coaching_forms.view", "settings.view"]);
    const manager = await pageProps();
    expect(dependencies.getCoachingForms).toHaveBeenCalledTimes(1);
    expect(manager.forms).toEqual([publishedForm]);
    expect(manager.formsUnavailable).toBe(false);
    expect(manager.canViewForms).toBe(true);
    expect(manager.defaultPublicLinkExpiryDays).toBe(14);
    expect(manager.canManage).toBe(true);
  });
});

describe("Coaching record route: access and failures", () => {
  it("reads nothing for a role without coaching.view", async () => {
    arrange(["coaching_responses.view", "coaching_links.manage", "coaching_forms.view"]);
    const element = await loadRoute();
    expect(element.type).toBe(PermissionDeniedState);
    for (const loader of [
      dependencies.getCoachingRecordDetailResult,
      dependencies.getCoachingRecordEventsResult,
      dependencies.getCoachingForms,
      dependencies.getCoachingRecordResponses,
      dependencies.getCoachingPublicLinks,
      dependencies.getSystemSettings,
    ]) {
      expect(loader).not.toHaveBeenCalled();
    }
  });

  it("answers a failed record read and a failed history with their error states, and a missing record with 404", async () => {
    arrange(["coaching.view", "coaching_responses.view"]);
    dependencies.getCoachingRecordDetailResult.mockResolvedValue({ ok: false });
    const failedRecord = await loadRoute();
    expect(failedRecord.type).toBe(ErrorState);
    expect(failedRecord.props.title).toBe("Không tải được phiếu Coaching");

    dependencies.getCoachingRecordDetailResult.mockResolvedValue({ data: null, ok: true });
    await expect(loadRoute()).rejects.toThrow("NEXT_NOT_FOUND");

    dependencies.getCoachingRecordDetailResult.mockResolvedValue({ data: record, ok: true });
    dependencies.getCoachingRecordEventsResult.mockResolvedValue({ ok: false });
    const failedHistory = await loadRoute();
    expect(failedHistory.type).toBe(ErrorState);
    expect(failedHistory.props.title).toBe("Không tải được lịch sử Coaching");
  });
});
